"""Declarative base and shared column mixins.

`Base.metadata` is the single object Alembic diffs against, so every model
module must be imported by `app.models.__init__` for autogenerate to see it.

Conventions (from `leo-sdd/features/001-onboarding/data-model.md`):

* UUID primary keys, generated by PostgreSQL rather than the application.
* `TIMESTAMPTZ` everywhere; never a naive timestamp.
* Enum-like columns are ``TEXT`` plus a ``CHECK`` constraint rather than a
  native PostgreSQL enum, because altering a CHECK is a plain migration
  while altering a native enum type is not.
"""

from __future__ import annotations

import uuid
from collections.abc import Sequence
from datetime import datetime

from sqlalchemy import CheckConstraint, DateTime, MetaData, func, text
from sqlalchemy.dialects.postgresql import UUID as PgUUID
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column


def enum_check(column: str, values: Sequence[str], name: str) -> CheckConstraint:
    """Build the ``CHECK (col IN (...))`` constraint for an enum-like column.

    Values are known literals defined in this codebase, never user input, so
    quoting them directly is safe and keeps the emitted SQL readable in the
    migration.
    """
    rendered = ", ".join(f"'{value}'" for value in values)
    return CheckConstraint(f"{column} IN ({rendered})", name=name)


# Deterministic constraint and index names. Without this, autogenerate emits
# migrations that cannot drop unnamed constraints on downgrade.
NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    """Shared declarative base for every ORM model."""

    metadata = MetaData(naming_convention=NAMING_CONVENTION)


class UUIDPrimaryKeyMixin:
    """UUID primary key produced by the database.

    `gen_random_uuid()` is built into PostgreSQL 13 and later, so the
    `pgcrypto` extension the data model mentions as optional is not needed.
    """

    id: Mapped[uuid.UUID] = mapped_column(
        PgUUID(as_uuid=True),
        primary_key=True,
        server_default=text("gen_random_uuid()"),
    )


class CreatedAtMixin:
    """`created_at` only, for append-only rows that are never updated."""

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
    )


class TimestampMixin(CreatedAtMixin):
    """`created_at` + `updated_at`, refreshed on every UPDATE."""

    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
        onupdate=func.now(),
    )
